def icono(nombre: str, clase: str = "") -> Markup:
    """Devuelve el <svg> del icono. Es decorativo: los lectores de pantalla lo ignoran."""
    trazos = _TRAZOS.get(nombre)
    if trazos is None:
        return Markup("")
    clases = f"icon {clase}".strip()
    return Markup(
        f'<svg class="{clases}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" '
        'fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" '
        f'stroke-linejoin="round" aria-hidden="true" focusable="false">{trazos}</svg>'
    )
